import time

from abc import ABC
from typing import Literal, Union, Optional, List
from taf.ul.alarms_watchdog import Alarm
from paramiko.ssh_exception import SSHException

from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import FallbackFaultNotExists
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.utilities.exceptions import FunctionTimeoutException
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success, verify_function_x_times


class FeatureNode(Node, ABC):
    def __init__(self, node_mrbts_id: str, node_alias: Optional[str] = None, node_vm: Union[str, dict] = None,
                 secondary_vm: Union[str, dict] = None, bts_host_ip: Optional[str] = "192.168.255.129",
                 external_dcap_host: Optional[str] = None, dcap_port: Optional[str] = "9443",
                 dcap_custom_profiles: Optional[dict] = None, hw_to_onair_timeout: Optional[int] = 900,
                 alarm_timer: Optional[int] = 60, source_sw: Optional[str] = None, target_sw: Optional[str] = None,
                 custom_allowed_alarms: Optional[list] = None, temporary_allowed_alarms: Optional[list] = None,
                 critical_alarms: List[Union[str, Alarm]] = None, pdu_config: Optional[list] = None,
                 logs_dir: Optional[str] = None, testline_scout_name: Optional[str] = None,
                 use_dcap: Optional[bool] = False, verify_syslog: Optional[bool] = True,
                 syslog_ignored_prints: Union[list, str] = None,
                 user_syslog_suspicious_prints: Union[list, str] = None,
                 webem_username: str = 'Nemuadmin', webem_password: str = 'nemuuser',
                 node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu",
                 check_mplane: bool = True, oran_files: dict = None, airphone_details: dict = None,
                 check_amf: bool = True, admin_setup_timeout: int = 120, setup_energy_saving: bool = False,
                 ru_manager_yaml_file: Union[str, None] = None, **kwargs):
        super().__init__(node_mrbts_id, node_alias, node_vm, secondary_vm, bts_host_ip, external_dcap_host, dcap_port,
                         dcap_custom_profiles, hw_to_onair_timeout, alarm_timer, source_sw, target_sw,
                         custom_allowed_alarms, temporary_allowed_alarms, critical_alarms, pdu_config,
                         logs_dir, testline_scout_name, use_dcap, verify_syslog, syslog_ignored_prints,
                         user_syslog_suspicious_prints, webem_username, webem_password, node_ssh_username,
                         node_ssh_password, check_mplane, oran_files, airphone_details, check_amf, admin_setup_timeout,
                         setup_energy_saving, ru_manager_yaml_file, **kwargs)
        self.netboot_changed = None
        self.smod_type = self.ssh_manager.get_module_type()

    @method_decorator("node_alias")
    def execute_reset_loop(self):
        wait_until_success(900, 1, self.reset_loop_and_wait_on_new_sw_activated, sw=self.source_sw)

    @method_decorator("node_alias")
    def clear_fallback_fault(self):
        if self.ssh_manager.file_exists("/ffs/run/config/fallbackCause.txt"):
            self.ssh_manager.execute_command("rm -rfv /ffs/run/config/fallbackCause.txt")
            return True
        return False

    @method_decorator("node_alias")
    def wait_on_all_modules(self):
        wait_until_success(1800, 30, self.verify_bts_if_not_fid23)

    @method_decorator("node_alias")
    def verify_bts_if_not_fid23(self):
        if not self.verify_if_fault_exists("23"):
            self.verify_bts_state()

    @method_decorator("node_alias")
    def perform_node_commissioning(self) -> None:
        test_logger("Performing node commissioning")
        self.admin.perform_commissioning(self.mrbts_id, self.scf_file, skip_parameter_relation_errors=True,
                                         should_activate=True, timeout=360)
        test_logger("Node commissioning finished")

    @method_decorator('node_alias')
    def verify_fallback_fault(self):
        if not self.verify_if_fault_exists(["4082", "4083", "4085", "4489"]):
            raise FallbackFaultNotExists("Fallback fault doesn't exists")

    @method_decorator("node_alias")
    def prepare_node_before_fallback(self):
        parameter = ""
        try:
            if len(self.systemModules) == 2:
                for parameter in ["actForceAutoReset", "actForceUnitAutoReset"]:
                    verify_function_x_times(3, 10, self.perform_parameter_recommissioning, parameter=parameter,
                                            dist_name=f"{self.mrbts_id}/MNL-1/MNLENT-1/FMCADM-1")
        except Exception as e:
            test_logger(e, 'debug')
            test_logger(f"Changing parameter {parameter} failed", 'error')
        self.netboot_changed = self.change_netboot_state("off")

    @method_decorator("node_alias")
    def perform_parameter_recommissioning(self, parameter, dist_name, value='true'):
        self.admin.perform_parameter_recommissioning(parameter=parameter, dist_name=dist_name, value=value,
                                                     operation="update", timeout=600,
                                                     skip_parameter_relation_errors=True)

    @method_decorator("node_alias")
    def change_netboot_state(self, state: Literal['on', 'off'], slave_smod: bool = False) -> bool:
        if state not in ("on", "off"):
            raise ValueError("Invalid state value. Excpected one of: ['on', 'off']")
        airscale_check_netboot = "uboot_env get netboot"
        fsmf_check_uboot = "uboot_env get uboot_recovery"
        airscale_command = "uboot_env set netboot=netboot_first" if state == "on" else "uboot_env del netboot"
        fsmf_command = "uboot_env set uboot_recovery=1" if state == "on" else "uboot_env set uboot_recovery=0"
        try:
            if self.smod_type in ("FSMF", "FSIH"):
                uboot_value = self.ssh_manager.execute_command(fsmf_check_uboot, slave_smod=slave_smod).rstrip()
                if uboot_value == "uboot_recovery=1" and state == "on" or \
                        uboot_value == "uboot_recovery=0" and state == "off":
                    return False
                output = self.ssh_manager.execute_command(fsmf_command, slave_smod=slave_smod).rstrip()
            else:
                netboot_value = self.ssh_manager.execute_command(airscale_check_netboot, slave_smod=slave_smod).rstrip()
                if netboot_value == "netboot=netboot_first" and state == "on" or \
                        netboot_value == "Variable netboot not found" and state == "off":
                    return False
                output = self.ssh_manager.execute_command(airscale_command, slave_smod=slave_smod).rstrip()
            if any(result in output for result in ["Added", "Deleted"]):
                test_logger(f"[{self.node_alias}] NetBoot turned {state}")
                return True
            else:
                raise Exception(f"[{self.node_alias}] NetBoot state didn't change")
        except Exception as e:
            raise e

    @method_decorator("node_alias")
    def reset_loop_and_wait_on_new_sw_activated(self, sw: str) -> None:
        airscale_command = "ddal -s ddal_boot_set_reset_loop_count 3 | ddal -s ddal_reboot_sm_site_graceful " \
                           "DDAL_REBOOT_SM_SHELF_SIDE_OWN"
        fsmf_command = "ddal -s ddal_boot_set_reset_loop_count 3 | ddal -s ddal_reboot_graceful"
        try:
            test_logger(f"[{self.node_alias}] Executing reset loop")
            self.ssh_manager.execute_command(fsmf_command if self.smod_type in ("FSMF", "FSIH")
                                             else airscale_command).rstrip()
            time.sleep(10)

            wait_until_success(600, 30, self.verify_active_sw_version_via_ssh, sw)
        except Exception as e:
            raise e

    @method_decorator("node_alias")
    def check_active_sw_version_via_ssh(self, sw: str) -> bool:
        def is_smod_pingable():
            if not self.is_smod_pingable(smod_ip=self.bts_host_ip):
                raise
        try:
            wait_until_success(300, 10, is_smod_pingable)
            command = "ls /ffs/run/ | grep Target.*p7 | grep -e 'FDSW\|SBTS' | sed 's:TargetBD_::;s:.xml.p7::'"
            active_sw = self.ssh_manager.execute_command(command, timeout="10").rstrip()
            test_logger(f"Active sw via ssh: {active_sw}", "DEBUG")
            active_sw_splited = active_sw.split("_")
            if "9" in active_sw_splited[2] and "SBTS" in active_sw_splited[0]:
                active_sw = active_sw.replace(active_sw_splited[0], "SBTS00")
            if 'FDSW' in sw:
                return 'FDSW' in active_sw
            return active_sw == sw
        except (SSHException, FunctionTimeoutException) as ssh_connection:
            test_logger(ssh_connection, "DEBUG")
            return False

    @method_decorator("node_alias")
    def verify_active_sw_version_via_ssh(self, sw: str) -> None:
        if not self.check_active_sw_version_via_ssh(sw):
            raise WrongSwVersion()

    @method_decorator("node_alias")
    def gather_pass_snapshot(self, snapshot_directory: str, operation: str):
        self.logsverify.gather_snapshot(logs_dir="",
                                        file_name=f"{operation}_pass_snapshot",
                                        snapshot_directory=snapshot_directory)

    @method_decorator("node_alias")
    def precondition_before_fallback(self) -> bool:
        if self.get_active_sw() == self.source_sw:
            test_logger(f"[{self.node_alias}] Preparing node for fallback")
            self.reset_admin()
            self.prepare_node_before_fallback()
            return True
        return False

    @method_decorator("node_alias")
    def verify_active_sw_after_fallback(self):
        self.verify_active_sw_version(self.source_sw)
